import { randomUUID } from "node:crypto"
import { expect, test } from "@playwright/test"
import pg from "pg"
import { e2eDatabaseUrl } from "../scripts/database-url.mjs"
import { ORGANIZER, SUMMER_CAMP_LINK } from "./support/accounts"
import { openEventList, signIn } from "./support/auth"

test("capture room assignment actions", async ({ page }) => {
  const db = new pg.Client({ connectionString: e2eDatabaseUrl() })
  const term = randomUUID()
  const alex = randomUUID()
  const robin = randomUUID()
  await db.connect()
  try {
    const { rows } = await db.query<{ id: string; organizationId: string }>(
      'SELECT id, "organizationId" FROM "event" WHERE "publicToken" = $1',
      [SUMMER_CAMP_LINK.split("/").at(-1)],
    )
    const { id: event, organizationId: organization } = rows[0]
    await db.query(
      `INSERT INTO "term" (id, "organizationId", "eventId", number, name, "startsOn", "endsOn", "priceCzk")
       SELECT $1, $2, $3, COALESCE(MAX(number), 0) + 1, 'Demo accommodation', '2029-01-01', '2029-01-07', 1000
       FROM "term" WHERE "eventId" = $3`,
      [term, organization, event],
    )
    await db.query(
      `INSERT INTO "room" (id, "organizationId", "termId", name, capacity, gender)
       VALUES ($1 || '-01', $2, $1, 'Room 101', 4, 'FEMALE'),
              ($1 || '-02', $2, $1, 'Room 102', 4, 'FEMALE')`,
      [term, organization],
    )
    await db.query(
      `INSERT INTO "application" (id, "organizationId", "eventId", "accessToken", "firstName", "lastName", "birthDate", gender, email, "consentAt")
       VALUES ($1, $3, $4, $1, 'Demo', '01', '2010-01-01', 'FEMALE', $1 || '@example.com', now()),
              ($2, $3, $4, $2, 'Demo', '02', '2010-01-01', 'FEMALE', $2 || '@example.com', now())`,
      [alex, robin, organization, event],
    )
    await db.query(
      `INSERT INTO "application_term" (id, "organizationId", "applicationId", "termId", status, "priceCzk")
       VALUES ($1, $3, $1, $4, 'CONFIRMED', 1000), ($2, $3, $2, $4, 'CONFIRMED', 1000)`,
      [alex, robin, organization, term],
    )
    await db.query(
      `INSERT INTO "room_assignment" (id, "organizationId", "applicationTermId", "roomId")
       VALUES ($1, $2, $1, $3)`,
      [robin, organization, term + "-01"],
    )

    await signIn(page, "organizer", ORGANIZER)
    await openEventList(page)
    await page.goto("/organizer/events/" + event + "/rooms?termId=" + term)
    await expect(page.getByRole("heading", { name: "Rooms of the selected term" })).toBeVisible()
    await expect(page.getByRole("button", { name: "Assign Demo 01 to a room" })).toBeVisible()
    await expect(page.getByRole("button", { name: "Actions for Demo 02" })).toBeVisible()
    await page.waitForLoadState("networkidle")
    const mobile = page.viewportSize()!.width === 360
    if (mobile) console.log("LAYOUT", process.env.SHOT_PHASE, JSON.stringify(await page.evaluate(() => ({
      width: document.documentElement.scrollWidth,
      nodes: [...document.querySelectorAll("body *")].map(e => ({name:e.localName,cls:e.className,right:e.getBoundingClientRect().right})).filter(n => n.right>360 && typeof n.cls==="string").slice(0,32)
    }))))
    // Keep the signed-in account out of the public comparison, including the avatar.
    const account = page.getByText(/organizator@/i).filter({visible:true})
    if (!mobile) {
      await expect(account).toBeVisible()
      await account.evaluate((email) => {
        const control = email.closest('button,[role="button"],a') || email.parentElement?.parentElement
        if (!control) throw new Error("Account control unavailable")
        control.setAttribute("data-capture-account", "")
      })
    }
    const captureStyle = "[data-capture-account] { visibility: hidden !important }"
    const person = page.getByRole("button", {name: "Actions for Demo 02"})
    await person.evaluate(e => e.scrollIntoView({block:"center",behavior:"instant"}))
    if (mobile) await person.tap()
    else await person.click()
    const move = mobile && process.env.SHOT_PHASE === "after"
      ? page.getByRole("dialog", {name:"Demo 02"}).getByRole("button",{name:"Move to another room…"})
      : page.getByRole("menuitem", {name:"Move to another room…"})
    await expect(move).toBeVisible()
    await page.screenshot({ path: process.env.SHOT_PATH!, animations:"disabled", style:captureStyle })
    if (mobile) await move.tap()
    else await move.click()
    const target = page.getByRole("radio",{name:/Room 102/})
    await expect(target).toBeVisible()
    await target.click()
    await expect(target).toBeChecked()
    if (mobile && process.env.SHOT_PHASE === "after") await expect(page.locator('[data-slot="sheet-content"]')).toHaveCount(0)
    await page.evaluate(() => document.fonts.ready)
    await page.screenshot({ path: process.env.SHOT_PATH!.replace(".png","-picker.png"), animations:"disabled", style:captureStyle })
  } finally {
    try {
      await db.query('DELETE FROM "application" WHERE id IN ($1, $2)', [alex, robin])
      await db.query('DELETE FROM "term" WHERE id = $1', [term])
    } finally {
      await db.end()
    }
  }
})
